import React, { useState, useCallback } from 'react';
import {
  Button,
  Select,
  Modal,
  MoneyInput,
  Checkbox,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { usePeriodJobPermissions } from '../../../hooks/usePeriodJobPermissions';
import { useAppDispatch } from '../../../store/hooks';
import { tscdService } from '../../../services/tscd/tscdService';
import type { DepreciationDto, DepreciationLineDto } from '../../../services/tscd/models';
import { DocumentProcessingLevelPill } from '../../../components/document/DocumentProcessingLevelPill';
import { MONTH_OPTIONS, yearOptions } from '../../../constants/voucher';
import { tscdPageLabels as L } from '../../../constants/tscdPageLabels';
import { formatVnd } from '../../../utils/formatters';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  DOCUMENT_PREPARED_LEVEL,
  formatDepreciationProcessingLevel,
} from '../../../utils/documentProcessingLevelDisplay';
import erp from '../../../styles/erpPage.module.css';
import df from '../../../styles/documentForm.module.css';
import { ListSearchRefreshButtons } from '../../../components/list/ListSearchRefreshButtons';

const TEST_ID = 'erp-dieu-chinh-khau-hao';
const labels = L.dieuChinhKhauHao;

const DieuChinhKhauHaoPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canRun: runPermitted } = usePeriodJobPermissions('depreciation');
  const now = new Date();
  const [month, setMonth] = useState(String(now.getMonth() + 1));
  const [year, setYear] = useState(String(now.getFullYear()));
  const [data, setData] = useState<DepreciationDto | null>(null);
  const [loading, setLoading] = useState(false);
  const [adjustLine, setAdjustLine] = useState<DepreciationLineDto | null>(null);
  const [adjustAmount, setAdjustAmount] = useState(0);
  const [adjustIsManual, setAdjustIsManual] = useState(true);
  const [saving, setSaving] = useState(false);
  const [amountError, setAmountError] = useState<string | undefined>();

  const load = useCallback(() => {
    setLoading(true);
    const m = Number(month);
    const y = Number(year);
    tscdService.getDepreciation(m, y)
      .then(setData)
      .catch(err => dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, labels.loadError),
        type: 'error',
      }))
      .finally(() => setLoading(false));
  }, [month, year, dispatch]);

  React.useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => { if (!cancelled) load(); }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [load]);

  const processingLevel = data?.processingLevel ?? null;
  const canAdjust = runPermitted && processingLevel === DOCUMENT_PREPARED_LEVEL;
  const hasLines = (data?.lines.length ?? 0) > 0;
  const isEmptyPeriod = !processingLevel && !hasLines;

  const openAdjust = (line: DepreciationLineDto) => {
    setAdjustLine(line);
    setAdjustAmount(Number(line.amount ?? 0));
    setAdjustIsManual(line.isManual ?? false);
    setAmountError(undefined);
  };

  const closeAdjust = () => {
    if (saving) return;
    setAdjustLine(null);
    setAmountError(undefined);
  };

  const handleSaveAdjust = async () => {
    if (!adjustLine?.id) return;
    if (!Number.isFinite(adjustAmount)) {
      setAmountError(labels.errAmount);
      return;
    }
    setSaving(true);
    try {
      await tscdService.adjustDepreciationLine(adjustLine.id, {
        amount: adjustAmount,
        isManual: adjustIsManual,
      });
      dispatchAppToast(dispatch, { message: labels.adjustSuccess, type: 'success' });
      setAdjustLine(null);
      load();
    } catch (e: unknown) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(e, labels.adjustError),
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={erp.page} data-testid={TEST_ID}>
      <div className={erp.pageHeader}>
        <div className={erp.titleBlock}>
          <h1 className={erp.title}>
            <i className="fas fa-edit" /> {labels.title}
          </h1>
        </div>
      </div>
      <div className={erp.filtersBar} data-testid={`${TEST_ID}-filters`}>
        <Select
          value={month}
          onChange={e => setMonth(e.target.value)}
          options={MONTH_OPTIONS}
          data-testid={`${TEST_ID}-month`}
        />
        <Select
          value={year}
          onChange={e => setYear(e.target.value)}
          options={yearOptions()}
          data-testid={`${TEST_ID}-year`}
        />
        <ListSearchRefreshButtons
          testIdPrefix={TEST_ID}
          onSearch={load}
          onRefresh={load}
          showSearch={false}
        />
      </div>
      <div className={erp.tableCard} data-testid={`${TEST_ID}-table`}>
        {loading ? (
          <div className={erp.loading}>{labels.loading}</div>
        ) : !data || isEmptyPeriod ? (
          <div className={erp.empty}>{labels.empty(month, year)}</div>
        ) : (
          <>
            <div className={erp.summaryBar}>
              <div className={erp.summaryItem}>
                <label className={erp.label}>{labels.processingLevel}</label>
                <DocumentProcessingLevelPill
                  label={formatDepreciationProcessingLevel(processingLevel)}
                  testId={`${TEST_ID}-level`}
                />
              </div>
              <div className={erp.summaryItem}>
                <label className={erp.label}>{labels.total}</label>
                <strong>{formatVnd(data.totalAmount)}</strong>
              </div>
            </div>
            {hasLines ? (
              <>
                <div className={df.section} style={{ margin: '0 0 12px', padding: '12px 16px' }}>
                  <h2 className={df.sectionTitle}>{labels.methodTitle}</h2>
                  <p style={{ margin: 0, fontSize: 13, lineHeight: 1.5 }}>{labels.methodNote}</p>
                </div>
                <div className={erp.tableWrapper}>
                  <table className={erp.table}>
                    <thead>
                      <tr>
                        <th>{labels.colCode}</th>
                        <th>{labels.colName}</th>
                        <th>{labels.colAccount}</th>
                        <th className={erp.colRight}>{labels.colOriginalCost}</th>
                        <th className={erp.colRight}>{labels.colAccumDep}</th>
                        <th className={erp.colRight}>{labels.colBookValue}</th>
                        <th className={erp.colRight}>{labels.colAmount}</th>
                        <th>{labels.colManual}</th>
                        {canAdjust ? <th /> : null}
                      </tr>
                    </thead>
                    <tbody>
                      {data.lines.map(l => (
                        <tr
                          key={l.fixedAssetId}
                          data-testid={`${TEST_ID}-row-${l.fixedAssetId}`}
                        >
                          <td><code>{l.assetCode}</code></td>
                          <td>{l.assetName}</td>
                          <td><code>{l.accountCode}</code></td>
                          <td className={erp.colRight}>{formatVnd(l.originalCost)}</td>
                          <td className={erp.colRight}>{formatVnd(l.accumulatedDepreciation)}</td>
                          <td className={erp.colRight}>
                            <strong>{formatVnd(l.bookValue)}</strong>
                          </td>
                          <td className={erp.colRight}>{formatVnd(l.amount)}</td>
                          <td>{l.isManual ? labels.badgeManual : '—'}</td>
                          {canAdjust ? (
                            <td>
                              <Button
                                variant="secondary"
                                onClick={() => openAdjust(l)}
                                data-testid={`${TEST_ID}-row-${l.fixedAssetId}-adjust`}
                              >
                                {labels.adjust}
                              </Button>
                            </td>
                          ) : null}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            ) : (
              <div className={erp.empty}>{labels.noLines}</div>
            )}
          </>
        )}
      </div>

      <Modal
        isOpen={!!adjustLine}
        size="sm"
        title={
          adjustLine
            ? `${labels.modalTitle} — ${adjustLine.assetCode}`
            : labels.modalTitle
        }
        onClose={closeAdjust}
      >
        {adjustLine ? (
          <div data-testid={`${TEST_ID}-adjust-modal`}>
            <p style={{ margin: '0 0 12px', fontSize: 13 }}>
              <code>{adjustLine.assetCode}</code> — {adjustLine.assetName}
            </p>
            <div className={df.field} style={{ marginBottom: 12 }}>
              <label className={df.label}>{labels.fieldAmount}</label>
              <MoneyInput
                value={adjustAmount}
                onChange={val => {
                  setAdjustAmount(val);
                  setAmountError(undefined);
                }}
                error={amountError}
                data-testid={`${TEST_ID}-adjust-amount`}
              />
            </div>
            <div style={{ marginBottom: 16 }}>
              <Checkbox
                label={labels.fieldIsManual}
                checked={adjustIsManual}
                onChange={e => setAdjustIsManual(e.target.checked)}
                data-testid={`${TEST_ID}-adjust-isManual`}
              />
            </div>
            <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
              <Button
                variant="secondary"
                onClick={closeAdjust}
                disabled={saving}
                data-testid={`${TEST_ID}-adjust-cancel`}
              >
                {labels.cancel}
              </Button>
              <Button
                variant="primary"
                onClick={() => { void handleSaveAdjust(); }}
                loading={saving}
                data-testid={`${TEST_ID}-adjust-save`}
              >
                {labels.save}
              </Button>
            </div>
          </div>
        ) : null}
      </Modal>
    </div>
  );
};

export default DieuChinhKhauHaoPage;
