import { hasPermissionCode } from '../utils/erpPermissionCode';

export { hasPermissionCode };

export type PeriodJobPermissionResource =
  | 'period-allocation'
  | 'period-closing'
  | 'tools-allocation'
  | 'cost-calculation'
  | 'carry-over'
  | 'period-close-final'
  | 'depreciation'
  | 'exchange-rate-revaluation';

function prefix(resource: PeriodJobPermissionResource): string {
  return `erp-finance:${resource}`;
}

/** Period job pages (`PeriodActionPanel`) — `erp-form-toolbar-permissions.md` § Tính toán. */
export function usePeriodJobPermissions(resource: PeriodJobPermissionResource) {
  const p = prefix(resource);
  const canWrite = hasPermissionCode(`${p}:write`);
  return {
    canRead: hasPermissionCode(`${p}:read`) || canWrite,
    /** `:run` hoặc Phase-1 `:write` (gộp quyền — sample four-feature-permissions). */
    canRun: hasPermissionCode(`${p}:run`) || canWrite,
    /** `:post` hoặc Phase-1 `:write`. */
    canPost: hasPermissionCode(`${p}:post`) || canWrite,
  };
}
